import{_ as s,o as a,c as i,a0 as o}from"./chunks/framework.CNXp-E7Q.js";const u=JSON.parse('{"title":"Tutorial: your first bupha run","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/first-run.md","filePath":"tutorials/first-run.md"}'),t={name:"tutorials/first-run.md"};function r(n,e,d,c,h,l){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="tutorial-your-first-bupha-run" tabindex="-1">Tutorial: your first bupha run <a class="header-anchor" href="#tutorial-your-first-bupha-run" aria-label="Permalink to &quot;Tutorial: your first bupha run&quot;">​</a></h1><p>Goal: push-triggered CI on a repo, end to end, in ~10 minutes.</p><p>bupha ships as tamias packages — the fleet is a <code>type: bupha</code> bundle and the <code>bupha</code> command is a <code>bins[]</code> shim pack (<code>libraries/bupha</code>, ADR-0006 amendment + T-012). You install the bundle with tamias, the provider unit runs the watcher engine through <code>tamias-driver-bupha host</code>, and GitHub pushes flow webhook → queue → worktree → pipeline → commit status.</p><p>Prereqs: <strong>Linux + systemd</strong> (provider units need systemd; the shell runner needs bash; macOS/Windows unsupported for now); git; the <code>tamias</code> CLI; the <code>bupha</code> command pack — <code>tamias install 9aia:bupha@&lt;version&gt;</code> from the org registry (needs <code>TAMIAS_REGISTRY_TOKEN</code>), or <code>scripts/pack.sh</code> + <code>tamias install --allow-drivers ./libraries/bupha</code> from a checkout — which registers <code>tamias-driver-bupha</code> into <code>$TAMIAS_HOME/drivers/</code> (<code>cargo build --release -p bupha-driver</code> from this repo produces the binary by hand); a stable public URL for the webhook — named cloudflared tunnel or a direct box; quick tunnels are convenient but flaky. Docker only if you use the dagger runner.</p><p>The shipped bundles live in <code>libraries/</code> — <code>ci-gate</code> (push gate on <code>main</code>) and <code>docs-deploy</code> (push to <code>docs</code> → site deploy). This tutorial walks <code>ci-gate</code>; swap the name for your own bundle.</p><ol><li><p><strong>Secrets first</strong> — names only in config, values in cuora (canonical, T-056):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BUPHA_TOKEN_VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cuora</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuora://bupha/BUPHA_TOKEN</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WEBHOOK_SECRET_VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cuora</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuora://bupha/BUPHA_WEBHOOK_SECRET</span></span></code></pre></div><p>(<code>BUPHA_TOKEN</code> is a repo-scoped PAT for statuses + hook management; <code>BUPHA_WEBHOOK_SECRET</code> is the HMAC secret GitHub signs deliveries with. Fallback when cuora isn&#39;t available: <code>~/.config/bupha/env</code> — the dev-mode / no-cuora leg (the OS-keyring leg was dropped post-T-077).)</p></li><li><p><code>tamias install &lt;ref&gt;</code> — fetch + unpack the bundle payload (driver <code>install</code> is a no-op; the payload&#39;s <code>fleet.toml</code> + <code>tamias.yaml</code> are the config sources).</p></li><li><p><code>tamias deploy ci-gate</code> — renders <code>bupha-watch.service</code> <strong>and</strong><code>bupha-worker.service</code> (one ingress mode each — enable ONE, see <a href="./../how-to/tamias-bundles.html">tamias bundles</a>) <strong>and</strong> runs the driver&#39;s <code>deploy</code> verb: merges <code>fleet.toml</code> with the manifest&#39;s <code>provider.ingress</code> and writes <code>~/.config/bupha/bundles/ci-gate.toml</code> — the file both units&#39; <code>tamias-driver-bupha host|worker --config …</code> consume.</p></li><li><p><code>tamias driver exec ci-gate hooks register --dry-run</code> — print the webhook plan, then <code>… hooks register</code> for real (needs the secrets above). This wires GitHub → the bundle&#39;s public URL — <strong>standalone/dev ingress</strong> (ADR-0007); production ingress is a peregrin campaign listener.</p></li><li><p><code>tamias service enable bupha-watch</code> — start the standalone watcher (<code>loginctl enable-linger</code> once for boot persistence); <code>bupha-worker</code> is the substrate/production alternative — see <a href="./../how-to/distributed-runners.html">distributed runners</a>.</p></li><li><p><code>tamias driver exec ci-gate health</code> — ping <code>/hook</code> + unit probe (JSON); <code>tamias driver exec ci-gate status</code> — per-unit is-active/is-enabled; <code>tamias driver exec ci-gate logs</code> — journalctl over the provider units.</p></li><li><p>Push. <code>ci/bupha</code> commit status appears; superseded/cancelled shas get honest error statuses.</p></li></ol><p>Done. Logs: <code>journalctl --user -u bupha-watch -f</code> (or <code>tamias driver exec ci-gate logs --lines 200</code>).</p><h2 id="local-reproduction-dev-harness" tabindex="-1">Local reproduction (dev harness) <a class="header-anchor" href="#local-reproduction-dev-harness" aria-label="Permalink to &quot;Local reproduction (dev harness)&quot;">​</a></h2><p>To reproduce a red run without touching the deployment, use the dev CLI — install the command pack (<code>scripts/pack.sh</code> then <code>tamias install --allow-drivers ./libraries/bupha</code> from this repo), then in the repo: <code>bupha doctor</code> checks the box against a config, <code>bupha run</code> executes the configured runner in the watched <code>dir</code> — the same pipeline, locally. <code>bupha watch</code> runs the whole engine standalone (no tamias, no peregrin) — the ADR-0007 fallback ingress, not the product path.</p>`,9)])])}const g=s(t,[["render",r]]);export{u as __pageData,g as default};
